        USE_TZ=True,
        LOGGING = {
            'version': 1,
            'disable_existing_loggers': False,
            'handlers': {
                'console': {
                    'class': 'logging.StreamHandler',
                },
            },
            'loggers': {
                'django.db.backends': {
                    'handlers': ['console'],
                    'level': 'DEBUG',
                },
            },
        }
    )

django.setup()

from django.db import models
from django.db.models import Count

# Define test models
class Author(models.Model):
    name = models.CharField(max_length=100)

    class Meta:
        app_label = 'test'

class Book(models.Model):
    title = models.CharField(max_length=100)
    authors = models.ManyToManyField(Author)

    class Meta:
        app_label = 'test'

# Create tables
from django.db import connection
with connection.schema_editor() as schema_editor:
    schema_editor.create_model(Author)
    schema_editor.create_model(Book)

# Create test data
author1 = Author.objects.create(name="Author 1")
author2 = Author.objects.create(name="Author 2")
book1 = Book.objects.create(title="Book 1")
book2 = Book.objects.create(title="Book 2")
book1.authors.add(author1, author2)
book2.authors.add(author1)

print("=== SQL queries executed ===")

print("\n1. Simple count:")
count1 = Book.objects.count()
print(f"Result: {count1}")

print("\n2. Count with annotation:")
count2 = Book.objects.annotate(author_count=Count('authors')).count()
print(f"Result: {count2}")

print("\n3. Count with annotation that's used in filter:")
count3 = Book.objects.annotate(author_count=Count('authors')).filter(author_count__gt=1).count()
print(f"Result: {count3}")

